class Solution {
public:
    long long evenProduct(vector<int>& nums) {
        long long answer = 0, oddRun = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            oddRun = nums[i] % 2 ? oddRun + 1 : 0;
            answer += i + 1 - oddRun;
        }
        return answer;
    }
};
